-- Source: database/functions/units/begin_unit_client_mutation_v1.sql
CREATE OR REPLACE FUNCTION public.begin_unit_client_mutation_v1(p_command_id uuid, p_command_name text, p_unit bigint, p_actor_id uuid, p_request_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_receipt public.client_mutation_receipts%ROWTYPE; v_inserted integer;
BEGIN
  IF p_actor_id IS NULL OR p_actor_id IS DISTINCT FROM auth.uid()
     OR p_command_id IS NULL OR p_unit IS NULL
     OR p_command_name !~ '^[a-z][a-z0-9_.]{2,95}$'
     OR p_request_sha256 !~ '^[0-9a-f]{64}$'
     OR NOT (CASE WHEN p_command_name IN ('occasion.create','occasion.setup.finalize')
       THEN public.can_create_occasion(p_unit)
       WHEN p_command_name='occasion.delete' THEN public.can_delete_occasion_in_unit(p_unit)
       WHEN p_command_name IN ('unit.information.save','unit.information.delete')
         THEN public.can_write_unit_information(p_unit)
       WHEN p_command_name IN ('unit.icon.save','unit.icon.delete')
         THEN public.can_write_unit_icons(p_unit)
       WHEN p_command_name IN ('unit.email_template.save','unit.email_template.reset','unit.email_banner.save')
         THEN public.can_write_unit_email_templates(p_unit)
       WHEN p_command_name IN ('profile.unit_access.delete','profile.unit_user.save') THEN public.can_manage_unit_users(p_unit)
       WHEN p_command_name='unit.config.save' THEN public.can_manage_unit_configuration(p_unit)
       WHEN p_command_name IN ('unit.cards.pause','unit.cards.disconnect') THEN public.can_manage_unit_configuration(p_unit) AND NOT public.is_demo_unit(p_unit)
       WHEN p_command_name='unit.order_history.delete' THEN public.can_manage_unit_configuration(p_unit) AND NOT public.is_demo_unit(p_unit)
       WHEN p_command_name='unit.delete' THEN public.can_manage_unit_configuration(p_unit) AND NOT public.is_demo_unit(p_unit)
       WHEN p_command_name IN ('unit.legal.save','unit.legal.submit') THEN public.can_manage_unit_legal_profile(p_unit)
       WHEN p_command_name IN ('unit.bank.save','unit.bank.link','unit.bank.user') THEN public.can_manage_unit_bank_accounts(p_unit)
       WHEN p_command_name='occasion.duplicate' THEN public.can_copy_occasion_target(p_unit)
       ELSE false END) THEN
    RAISE insufficient_privilege USING MESSAGE='invalid unit mutation receipt claim';
  END IF;
  INSERT INTO public.client_mutation_receipts
    (command_id,command_name,unit,actor_id,request_sha256)
  VALUES (p_command_id,p_command_name,p_unit,p_actor_id,p_request_sha256)
  ON CONFLICT (command_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  SELECT * INTO STRICT v_receipt FROM public.client_mutation_receipts
    WHERE command_id=p_command_id FOR UPDATE;
  IF v_receipt.command_name IS DISTINCT FROM p_command_name
     OR v_receipt.occasion IS NOT NULL OR v_receipt.unit IS DISTINCT FROM p_unit
     OR v_receipt.actor_id IS DISTINCT FROM p_actor_id OR v_receipt.actor_client_id IS NOT NULL
     OR v_receipt.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
    RAISE invalid_parameter_value USING MESSAGE='command id was already used with different request data';
  END IF;
  IF v_receipt.status='completed' THEN
    RETURN jsonb_build_object('disposition','replay','response',v_receipt.response);
  ELSIF v_receipt.status='expired' THEN
    RETURN jsonb_build_object('disposition','replay',
      'response',public.expired_client_mutation_response_v1(v_receipt));
  END IF;
  IF v_inserted<>1 THEN RAISE serialization_failure
    USING MESSAGE='incomplete mutation receipt cannot be resumed'; END IF;
  RETURN jsonb_build_object('disposition','claimed');
END; $function$
;
REVOKE ALL ON FUNCTION public.begin_unit_client_mutation_v1(p_command_id uuid, p_command_name text, p_unit bigint, p_actor_id uuid, p_request_sha256 text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.begin_unit_client_mutation_v1(uuid,text,bigint,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.begin_unit_client_mutation_v1(uuid,text,bigint,uuid,text) TO service_role;


-- Source: database/functions/eshop_stripe/disconnect.sql
CREATE OR REPLACE FUNCTION public.get_stripe_disconnect_impact(p_unit bigint,p_livemode boolean)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE c eshop.stripe_connections; result jsonb;
BEGIN
 PERFORM public.check_stripe_unit_manager_internal(p_unit,auth.uid());
 SELECT * INTO c FROM eshop.stripe_connections WHERE unit_id=p_unit AND livemode=p_livemode AND state IN ('connected','restricted','revoked')
  ORDER BY (state<>'revoked') DESC,created_at DESC LIMIT 1;
 IF c.id IS NULL THEN RAISE EXCEPTION 'STRIPE_CONNECTION_UNAVAILABLE'; END IF;
 SELECT jsonb_build_object('connectionId',c.id,'businessName',c.business_name,
  'openAttempts',count(*) FILTER(WHERE state IN ('preparing','open','uncertain') OR lease_expires_at>statement_timestamp() OR refund_cursor IS NOT NULL OR session_lookup_cursor IS NOT NULL),
  'historyCount',count(*),'lastSyncedAt',CASE WHEN bool_or(last_synced_at IS NULL) THEN NULL ELSE min(last_synced_at) END,
  'disconnectState',(SELECT state FROM eshop.stripe_disconnect_intents WHERE connection_id=c.id AND state<>'completed')) INTO result
 FROM eshop.stripe_checkout_attempts WHERE connection_id=c.id;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.get_stripe_disconnect_impact(bigint,boolean) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.get_stripe_disconnect_impact(bigint,boolean) TO authenticated;

CREATE OR REPLACE FUNCTION public.begin_stripe_disconnect(p_unit bigint,p_livemode boolean,p_expected_connection uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE c eshop.stripe_connections; intent eshop.stripe_disconnect_intents;
BEGIN
 PERFORM public.check_stripe_unit_manager_internal(p_unit,auth.uid());
 PERFORM 1 FROM public.forms f JOIN public.occasions o ON o.id=f.occasion WHERE o.unit=p_unit ORDER BY f.id FOR UPDATE OF f;
 PERFORM 1 FROM public.units WHERE id=p_unit FOR UPDATE;
 -- Completed intents also retain their binding. A lost final response must
 -- resume that same intent after the connection was retired, not dispatch again.
 SELECT i.* INTO intent FROM eshop.stripe_disconnect_intents i
 JOIN eshop.stripe_connections stored ON stored.id=i.connection_id
 WHERE i.connection_id=p_expected_connection AND i.actor=auth.uid()
  AND stored.unit_id=p_unit AND stored.livemode=p_livemode
 ORDER BY i.created_at DESC LIMIT 1;
 IF FOUND THEN RETURN jsonb_build_object('intentId',intent.id); END IF;
 SELECT * INTO c FROM eshop.stripe_connections WHERE id=p_expected_connection AND unit_id=p_unit AND livemode=p_livemode AND state IN ('connected','restricted') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'STRIPE_RECIPIENT_CHANGED'; END IF;
 SELECT * INTO intent FROM eshop.stripe_disconnect_intents WHERE connection_id=c.id AND state<>'completed';
 IF FOUND THEN
  IF intent.actor<>auth.uid() THEN RAISE EXCEPTION 'STRIPE_DISCONNECT_PENDING'; END IF;
  RETURN jsonb_build_object('intentId',intent.id);
 END IF;
 IF EXISTS(SELECT 1 FROM eshop.stripe_connection_flows WHERE unit_id=p_unit AND livemode=p_livemode AND expires_at>clock_timestamp() AND state IN ('pending','claimed','uncertain')) THEN RAISE EXCEPTION 'STRIPE_CONNECTION_FLOW_PENDING'; END IF;
 IF EXISTS(SELECT 1 FROM eshop.stripe_checkout_attempts WHERE connection_id=c.id AND
  (state IN ('preparing','open','uncertain') OR lease_expires_at>clock_timestamp() OR refund_cursor IS NOT NULL OR session_lookup_cursor IS NOT NULL)) THEN RAISE EXCEPTION 'STRIPE_DISCONNECT_OPEN_ATTEMPTS'; END IF;
 PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('stripe.connect',p_unit,c.organization_id),jsonb_build_object('actor',auth.uid(),'unit',p_unit,'organization',c.organization_id));
 INSERT INTO eshop.stripe_disconnect_intents(connection_id,actor) VALUES(c.id,auth.uid()) RETURNING * INTO intent;
 UPDATE eshop.stripe_connections SET paused=true,next_check_at=clock_timestamp() WHERE id=c.id;
 INSERT INTO eshop.stripe_connection_audit(connection_id,actor,action) VALUES(c.id,auth.uid(),'paused');
 RETURN jsonb_build_object('intentId',intent.id);
END $$;
REVOKE ALL ON FUNCTION public.begin_stripe_disconnect(bigint,boolean,uuid) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.begin_stripe_disconnect(bigint,boolean,uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.claim_stripe_disconnect_internal(p_intent uuid,p_actor uuid,p_livemode boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE intent eshop.stripe_disconnect_intents; c eshop.stripe_connections;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO STRICT intent FROM eshop.stripe_disconnect_intents WHERE id=p_intent AND actor=p_actor FOR UPDATE;
 SELECT * INTO STRICT c FROM eshop.stripe_connections WHERE id=intent.connection_id AND livemode=p_livemode;
 PERFORM public.check_stripe_unit_manager_internal(c.unit_id,p_actor);
 IF intent.state='completed' THEN RETURN jsonb_build_object('disposition','replay','result',intent.result); END IF;
 IF intent.state<>'pending' THEN RETURN jsonb_build_object('disposition','uncertain'); END IF;
 UPDATE eshop.stripe_disconnect_intents SET state='claimed',claimed_at=clock_timestamp() WHERE id=intent.id;
 RETURN jsonb_build_object('disposition','dispatch','accountId',c.account_id);
END $$;
REVOKE ALL ON FUNCTION public.claim_stripe_disconnect_internal(uuid,uuid,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_stripe_disconnect_internal(uuid,uuid,boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.finish_stripe_disconnect_internal(p_intent uuid,p_success boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE intent eshop.stripe_disconnect_intents; v_result jsonb;
BEGIN
 PERFORM public.require_service_role();
 -- Lock connection before intent, matching lifecycle completion.
 PERFORM 1 FROM eshop.stripe_connections WHERE id=(SELECT connection_id FROM eshop.stripe_disconnect_intents WHERE id=p_intent) FOR UPDATE;
 SELECT * INTO STRICT intent FROM eshop.stripe_disconnect_intents WHERE id=p_intent FOR UPDATE;
 IF intent.state='completed' THEN RETURN intent.result; END IF;
 IF intent.state<>'claimed' OR p_success IS NULL THEN RAISE EXCEPTION 'STRIPE_DISCONNECT_INVALID'; END IF;
 IF NOT p_success THEN
  UPDATE eshop.stripe_disconnect_intents SET state='uncertain' WHERE id=intent.id;
  UPDATE eshop.stripe_connections SET next_check_at=clock_timestamp() WHERE id=intent.connection_id;
  RETURN jsonb_build_object('disconnected',false,'uncertain',true);
 END IF;
 v_result:=jsonb_build_object('disconnected',true);
 UPDATE eshop.stripe_connections SET state='revoked',paused=true,charges_enabled=false,card_payments_active=false,payouts_enabled=false,
  status_lease=NULL,status_lease_expires_at=NULL,checked_at=clock_timestamp(),next_check_at=clock_timestamp()+interval '1 day' WHERE id=intent.connection_id;
 UPDATE eshop.stripe_disconnect_intents SET state='completed',result=v_result,completed_at=clock_timestamp() WHERE id=intent.id;
 INSERT INTO eshop.stripe_connection_audit(connection_id,actor,action) VALUES(intent.connection_id,intent.actor,'revoked');
 RETURN v_result;
END $$;
REVOKE ALL ON FUNCTION public.finish_stripe_disconnect_internal(uuid,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.finish_stripe_disconnect_internal(uuid,boolean) TO service_role;


-- Source: database/functions/authoring/finance.sql
-- Shared transport for current organizer bank management. Existing typed
-- predicates and bank writers own all policy, normalization and provider intents.
CREATE OR REPLACE FUNCTION public.manage_bank_authoring(
 p_unit bigint,p_organization bigint,p_action text,p_payload jsonb,p_command_id uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE unit_id bigint:=p_unit; bank bigint:=(p_payload->>'accountId')::bigint; result jsonb; begun jsonb; hash text; lim int:=coalesce((p_payload->>'limit')::int,50); ident bigint;
BEGIN
 IF unit_id IS NULL AND bank IS NOT NULL THEN
  SELECT r.unit INTO unit_id FROM public.client_mutation_receipts r WHERE r.command_id=p_command_id AND r.actor_id=auth.uid() AND r.command_name='unit.bank.'||p_action;
  IF unit_id IS NULL THEN
   SELECT link.unit INTO unit_id FROM eshop.unit_bank_accounts link WHERE link.bank_account=bank
    AND public.can_manage_bank_account(bank) AND public.can_manage_unit_bank_accounts(link.unit) ORDER BY link.unit LIMIT 1;
  END IF;
 END IF;
 PERFORM public.lock_people_scope_internal_v1(NULL,p_organization,unit_id);
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>16384 OR lim NOT BETWEEN 1 AND 100 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid bank request'; END IF;
 IF p_action='list' THEN
  -- Preserve the ordinary demo read rule, but never its connection secrets.
  IF NOT public.can_read_unit_bank_accounts(unit_id) THEN RAISE insufficient_privilege USING MESSAGE='bank reader required'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]') INTO result FROM (
   SELECT b.id,b.title,b.account_number AS "accountNumber",b.account_number_human_readable AS "displayNumber",b.creditor_name AS "creditorName",b.type,b.supported_currencies AS currencies,l.priority,
    public.can_manage_bank_account(b.id) AS "canManage"
   FROM eshop.unit_bank_accounts l JOIN eshop.bank_accounts b ON b.id=l.bank_account
   WHERE l.unit=unit_id AND (p_payload->>'after' IS NULL OR b.id>(p_payload->>'after')::bigint) ORDER BY b.id LIMIT lim) page;
  RETURN jsonb_build_object('items',result);
 ELSIF p_action='candidates' THEN
  IF NOT public.can_manage_unit_bank_accounts(unit_id) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]') INTO result FROM (
   SELECT b.id,b.title,b.account_number AS "accountNumber",b.type FROM eshop.bank_accounts b
   WHERE public.can_link_bank_account_to_unit(b.id,unit_id) AND (p_payload->>'after' IS NULL OR b.id>(p_payload->>'after')::bigint) ORDER BY b.id LIMIT lim) page;
  RETURN jsonb_build_object('items',result);
 END IF;
 -- Stored link is required for every account operation except explicit linking.
 IF p_action='link' THEN
  PERFORM 1 FROM eshop.unit_bank_accounts WHERE unit=unit_id AND bank_account=bank FOR UPDATE;
  IF (p_payload->>'priority' IS NULL OR FOUND) THEN
   IF NOT public.can_manage_unit_bank_accounts(unit_id) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  ELSIF NOT public.can_link_bank_account_to_unit(bank,unit_id) THEN RAISE insufficient_privilege USING MESSAGE='bank admin and target unit manager required'; END IF;
 ELSIF p_action='save' AND bank IS NULL THEN
  IF NOT public.can_manage_unit_bank_accounts(unit_id) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 ELSE
  PERFORM 1 FROM eshop.unit_bank_accounts WHERE unit=unit_id AND bank_account=bank FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='bank is not linked to selected unit'; END IF;
  PERFORM 1 FROM eshop.bank_account_users WHERE bank_account=bank AND "user"=auth.uid() FOR SHARE;
  IF p_action='users' THEN
   IF NOT public.can_read_bank_account_users(bank,unit_id) THEN RAISE insufficient_privilege USING MESSAGE='bank user reader required'; END IF;
  ELSIF NOT public.can_manage_unit_bank_accounts(unit_id) OR NOT public.can_manage_bank_account(bank) THEN RAISE insufficient_privilege USING MESSAGE='bank admin and selected linked manager required'; END IF;
 END IF;
 IF p_action='users' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.user_id),'[]') INTO result FROM (
   SELECT * FROM public.get_bank_account_users(bank,unit_id) x
   WHERE p_payload->>'afterUser' IS NULL OR x.user_id>(p_payload->>'afterUser')::uuid ORDER BY x.user_id LIMIT lim) page;
  RETURN jsonb_build_object('items',result);
 ELSIF p_action='status' THEN
  result:=public.get_bank_sync_connection(bank);
  RETURN jsonb_build_object('connection',CASE WHEN result IS NULL THEN NULL ELSE result-ARRAY['receiving_address','remote_bank_account_id','last_error'] END);
 ELSIF p_action='operations' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page."createdAt" DESC,page.id DESC),'[]') INTO result FROM (
   SELECT id,operation,state,created_at AS "createdAt",updated_at AS "updatedAt" FROM eshop.bank_sync_operations
   WHERE bank_account_id=bank AND (p_payload->>'before' IS NULL OR (created_at,id)<((p_payload#>>'{before,createdAt}')::timestamptz,(p_payload#>>'{before,id}')::uuid))
   ORDER BY created_at DESC,id DESC LIMIT lim) page;
  RETURN jsonb_build_object('items',result);
 ELSIF p_action='observations' THEN
  -- The canonical observation owner omits source mail bodies and credentials.
  SELECT coalesce(jsonb_agg(jsonb_build_object('deliveryId',x->'delivery_id','receivedAt',x->'received_at','outcome',x->'outcome')),'[]') INTO result FROM jsonb_array_elements(public.get_bank_sync_observations(bank,lim)) x;
  RETURN jsonb_build_object('items',result);
 END IF;
 IF p_action NOT IN ('save','link','user') OR p_command_id IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='bank command required'; END IF;
 hash:=encode(extensions.digest(jsonb_build_object('unit',unit_id,'action',p_action,'payload',p_payload)::text,'sha256'),'hex');
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.bank.'||p_action,unit_id,auth.uid(),hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 IF p_action='save' THEN
  ident:=public.update_bank_account(bank,p_payload->>'accountNumber',p_payload->>'title',p_payload->>'type',
   CASE WHEN p_payload->'currencies' IS NULL OR p_payload->'currencies'='null'::jsonb THEN NULL ELSE ARRAY(SELECT jsonb_array_elements_text(p_payload->'currencies')) END,p_payload->>'displayNumber',unit_id,p_payload->>'creditorName');
  result:=jsonb_build_object('accountId',ident,'detailsSyncPending',EXISTS(SELECT 1 FROM eshop.bank_sync_operations WHERE bank_account_id=ident AND operation='update_details' AND state<>'completed'));
 ELSIF p_action='user' THEN
  PERFORM public.update_bank_account_user(bank,p_payload->>'email',(p_payload->>'isAdmin')::boolean,(p_payload->>'isSupport')::boolean);
  result:=jsonb_build_object('accountId',bank);
 ELSE
  PERFORM public.link_bank_account_to_unit(bank,unit_id,(p_payload->>'priority')::int,coalesce((p_payload->>'force')::boolean,false));
  result:=jsonb_build_object('accountId',bank,'priority',p_payload->'priority');
 END IF;
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,unit_id,'unit.bank.'||p_action,'bank_account',coalesce(ident,bank),CASE WHEN p_action='save' AND bank IS NULL THEN 'insert' ELSE 'update' END,result);
END $$;
REVOKE ALL ON FUNCTION public.manage_bank_authoring(bigint,bigint,text,jsonb,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.manage_bank_authoring(bigint,bigint,text,jsonb,uuid) TO authenticated;

-- Scope admission and the original durable provider intent commit together.
CREATE OR REPLACE FUNCTION public.begin_delegated_bank_sync_operation(p_id uuid,p_account_id bigint,p_operation text,p_hash text,p_unit bigint,p_organization bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.manage_bank_authoring(p_unit,p_organization,'status',jsonb_build_object('accountId',p_account_id));
 IF p_operation NOT IN ('sync','suspend','resume') THEN RAISE invalid_parameter_value USING MESSAGE='delegated bank operation unsupported'; END IF;
 RETURN public.begin_bank_sync_operation(p_id,p_account_id,p_operation,p_hash);
END $$;
REVOKE ALL ON FUNCTION public.begin_delegated_bank_sync_operation(uuid,bigint,text,text,bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.begin_delegated_bank_sync_operation(uuid,bigint,text,text,bigint,bigint) TO authenticated;

CREATE OR REPLACE FUNCTION public.manage_card_refund_authoring(p_occasion bigint,p_organization bigint,p_unit bigint,p_order bigint,p_payload jsonb DEFAULT NULL,p_command_id uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_order AND occasion=p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='order scope changed'; END IF;
 IF p_payload IS NULL THEN
  result:=public.get_stripe_order_admin_detail(p_order);
  IF result IS NULL THEN RETURN NULL; END IF;
  RETURN (result-'dashboardUrl')||jsonb_build_object('tickets',(SELECT coalesce(jsonb_agg(x- 'label'),'[]') FROM jsonb_array_elements(result->'tickets') x));
 END IF;
 RETURN public.decide_stripe_partial_refund_client_sync_v1(p_order,p_payload->>'action',ARRAY(SELECT jsonb_array_elements_text(p_payload->'ticketIds'))::bigint[],p_payload->>'note',(p_payload->>'expectedRefundedMinor')::bigint,p_command_id);
END $$;
REVOKE ALL ON FUNCTION public.manage_card_refund_authoring(bigint,bigint,bigint,bigint,jsonb,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.manage_card_refund_authoring(bigint,bigint,bigint,bigint,jsonb,uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.set_stripe_unit_paused_client_sync_v1(p_unit bigint,p_livemode boolean,p_paused boolean,p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE begun jsonb; hash text;
BEGIN
 PERFORM public.check_stripe_unit_manager_internal(p_unit,auth.uid());
 hash:=encode(extensions.digest(jsonb_build_object('unit',p_unit,'live',p_livemode,'paused',p_paused)::text,'sha256'),'hex');
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.cards.pause',p_unit,auth.uid(),hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 PERFORM public.set_stripe_unit_paused(p_unit,p_livemode,p_paused);
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.cards.pause','unit',p_unit,'update',jsonb_build_object('state',public.get_stripe_unit_connection(p_unit,p_livemode)));
END $$;
REVOKE ALL ON FUNCTION public.set_stripe_unit_paused_client_sync_v1(bigint,boolean,boolean,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.set_stripe_unit_paused_client_sync_v1(bigint,boolean,boolean,uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.begin_stripe_disconnect_client_sync_v1(p_unit bigint,p_livemode boolean,p_expected_connection uuid,p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE begun jsonb; hash text; result jsonb;
BEGIN
 PERFORM public.check_stripe_unit_manager_internal(p_unit,auth.uid());
 hash:=encode(extensions.digest(jsonb_build_object('unit',p_unit,'live',p_livemode,'connection',p_expected_connection)::text,'sha256'),'hex');
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.cards.disconnect',p_unit,auth.uid(),hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 result:=public.begin_stripe_disconnect(p_unit,p_livemode,p_expected_connection);
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.cards.disconnect','unit',p_unit,'update',result);
END $$;
REVOKE ALL ON FUNCTION public.begin_stripe_disconnect_client_sync_v1(bigint,boolean,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.begin_stripe_disconnect_client_sync_v1(bigint,boolean,uuid,uuid) TO authenticated;


-- Source: database/functions/authoring/agenda.sql
-- Bounded organizer tabs. Existing aggregate commands remain the write owners.
CREATE OR REPLACE FUNCTION public.manage_unit_agenda(p_unit bigint,p_organization bigint,p_action text,p_payload jsonb,p_command_id uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb; begun jsonb; hash text; lim int:=coalesce((p_payload->>'limit')::int,50);
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,p_organization,p_unit);
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>786432 OR lim NOT BETWEEN 1 AND 100 THEN RAISE invalid_parameter_value USING MESSAGE='invalid organizer agenda'; END IF;
 IF p_action='quotes.list' THEN
  IF NOT public.can_read_unit_information(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit information reader required'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]') INTO result FROM (
   SELECT i.id,i.title,i.description,i.type,i.is_hidden AS "isHidden",i."order",i.data,coalesce(v.version,0) AS "aggregateVersion"
   FROM public.information i LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='information' AND v.scope_type='unit' AND v.scope_id=p_unit AND v.aggregate_id=i.id::text
   WHERE i.unit=p_unit AND i.occasion IS NULL AND i.information_hidden IS NULL AND i.type='quote' AND (p_payload->>'after' IS NULL OR i.id>(p_payload->>'after')::bigint) ORDER BY i.id LIMIT lim) page;
  RETURN jsonb_build_object('items',result);
 ELSIF p_action IN ('quotes.save','quotes.delete') THEN
  IF p_action='quotes.save' THEN
   IF p_payload#>>'{quote,type}' IS DISTINCT FROM 'quote' THEN RAISE invalid_parameter_value USING MESSAGE='quote type required'; END IF;
   IF p_payload#>>'{quote,id}' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.information WHERE id=(p_payload#>>'{quote,id}')::bigint AND unit=p_unit AND occasion IS NULL AND type='quote') THEN RAISE insufficient_privilege USING MESSAGE='quote unavailable'; END IF;
   RETURN public.save_unit_information_client_sync_v1(p_unit,p_command_id,(p_payload->>'expectedVersion')::bigint,p_payload->'quote');
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.information WHERE id=(p_payload->>'quoteId')::bigint AND unit=p_unit AND occasion IS NULL AND type='quote') THEN
   -- The original owner must still be able to return a receipt after deletion.
   IF NOT EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=auth.uid() AND unit=p_unit AND command_name='unit.information.delete') THEN RAISE insufficient_privilege USING MESSAGE='quote unavailable'; END IF;
  END IF;
  RETURN public.delete_unit_information_client_sync_v1(p_unit,(p_payload->>'quoteId')::bigint,p_command_id,(p_payload->>'expectedVersion')::bigint);
 ELSIF p_action='legal.inspect' THEN
  result:=public.get_unit_legal_profile(p_unit);
  RETURN jsonb_set(result,'{profile}',(result->'profile')-ARRAY['reviewNote','reviewSource']);
 ELSIF p_action IN ('legal.save','legal.submit') THEN
  IF NOT public.can_manage_unit_legal_profile(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit legal manager required'; END IF;
  hash:=encode(extensions.digest(jsonb_build_object('unit',p_unit,'action',p_action,'payload',p_payload)::text,'sha256'),'hex');
  begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.'||p_action,p_unit,auth.uid(),hash);
  IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
  result:=CASE WHEN p_action='legal.save' THEN public.save_unit_legal_profile(p_unit,(p_payload->>'expectedRevision')::bigint,p_payload->'profile')
   ELSE public.submit_unit_verification(p_unit,(p_payload->>'expectedRevision')::bigint) END;
  IF result ? 'profile' THEN result:=jsonb_set(result,'{profile}',(result->'profile')-ARRAY['reviewNote','reviewSource']); END IF;
  IF result->>'code'<>'200' THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,CASE WHEN result->>'code'='409' THEN 'conflict' ELSE 'rejected' END,(result->>'code')::int,result); END IF;
  RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.'||p_action,'unit_legal_profile',p_unit,'update',result);
 END IF;
 RAISE invalid_parameter_value USING MESSAGE='unsupported organizer agenda';
END $$;
REVOKE ALL ON FUNCTION public.manage_unit_agenda(bigint,bigint,text,jsonb,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.manage_unit_agenda(bigint,bigint,text,jsonb,uuid) TO authenticated;

-- A deleted organizer has no live membership row. Its exact actor-owned
-- tombstone may only replay the recorded result; it cannot authorize a new effect.
CREATE OR REPLACE FUNCTION public.delete_unit_client_sync_v1(p_unit bigint,p_command_id uuid,p_organization bigint DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE hash text; receipt public.client_mutation_receipts; organization_id bigint; begun jsonb;
BEGIN
 IF auth.uid() IS NULL OR p_command_id IS NULL THEN RAISE insufficient_privilege USING MESSAGE='authenticated command required'; END IF;
 hash:=encode(extensions.digest(jsonb_build_object('unit',p_unit)::text,'sha256'),'hex');
 SELECT * INTO receipt FROM public.client_mutation_receipts WHERE command_id=p_command_id AND command_name='unit.delete' AND unit=p_unit AND actor_id=auth.uid() AND request_sha256=hash;
 IF FOUND AND receipt.status IN ('completed','expired') THEN
  organization_id:=(receipt.response#>>'{data,organizationId}')::bigint;
  IF (p_organization IS NOT NULL AND p_organization IS DISTINCT FROM organization_id)
   OR NOT EXISTS(SELECT 1 FROM public.user_info WHERE id=auth.uid() AND organization=organization_id)
   OR (EXISTS(SELECT 1 FROM public.units WHERE id=p_unit) AND NOT public.can_manage_unit_configuration(p_unit)) THEN RAISE insufficient_privilege USING MESSAGE='organizer tombstone unavailable'; END IF;
  IF receipt.status='expired' THEN RETURN public.expired_client_mutation_response_v1(receipt); END IF;
  RETURN receipt.response;
 END IF;
 PERFORM public.lock_people_scope_internal_v1(NULL,p_organization,p_unit);
 SELECT organization INTO organization_id FROM public.units WHERE id=p_unit FOR UPDATE;
 IF organization_id IS NULL OR NOT public.can_manage_unit_configuration(p_unit) OR public.is_demo_unit(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.delete',p_unit,auth.uid(),hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 PERFORM public.delete_unit(p_unit);
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.delete','unit',p_unit,'delete',jsonb_build_object('unitId',p_unit,'organizationId',organization_id));
END $$;
REVOKE ALL ON FUNCTION public.delete_unit_client_sync_v1(bigint,uuid,bigint) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.delete_unit_client_sync_v1(bigint,uuid,bigint) TO authenticated;


-- Source: database/functions/authoring/lifecycle.sql
-- The SQL receipt is still the canonical create/delete owner. This ledger owns
-- only completion of the existing copy's two media references in the image Worker.
CREATE TABLE IF NOT EXISTS public.occasion_media_jobs(
 command_id uuid PRIMARY KEY,actor_id uuid NOT NULL,organization bigint NOT NULL,
 source_unit bigint NOT NULL,target_unit bigint NOT NULL,source_occasion bigint NOT NULL,
 target_occasion bigint NOT NULL,action text NOT NULL CHECK(action IN ('copy','delete')),
 request_sha256 text NOT NULL,state text NOT NULL CHECK(state IN ('pending','complete')),
 media jsonb NOT NULL DEFAULT '[]',apply_command uuid NOT NULL DEFAULT gen_random_uuid(),
 created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
ALTER TABLE public.occasion_media_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.occasion_media_jobs FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.get_occasion_media_job(p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE job public.occasion_media_jobs;
BEGIN
 SELECT * INTO job FROM public.occasion_media_jobs WHERE command_id=p_command_id;
 IF job.command_id IS NULL OR job.actor_id IS DISTINCT FROM auth.uid() THEN RAISE insufficient_privilege USING MESSAGE='lifecycle intent unavailable'; END IF;
 PERFORM public.lock_people_scope_internal_v1(NULL,job.organization,job.source_unit);
 IF job.action='delete' THEN
  IF NOT public.can_delete_occasion_in_unit(job.source_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 ELSE
  PERFORM public.lock_people_scope_internal_v1(NULL,job.organization,job.target_unit);
  IF NOT (public.can_copy_occasion_source(job.source_occasion) OR (NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=job.source_occasion) AND public.can_copy_occasion_target(job.source_unit))) OR NOT public.can_copy_occasion_target(job.target_unit)
   OR (EXISTS(SELECT 1 FROM public.occasions WHERE id=job.target_occasion) AND NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=job.target_occasion AND unit=job.target_unit AND organization=job.organization)) THEN
   RAISE insufficient_privilege USING MESSAGE='copy scope changed'; END IF;
 END IF;
 RETURN jsonb_build_object('commandId',job.command_id,'unitId',job.source_unit,'targetUnitId',job.target_unit,
  'occasionId',job.target_occasion,'sourceOccasionId',job.source_occasion,'action',job.action,'state',job.state,'media',job.media,
  'assetDisposition',CASE WHEN job.action='delete' THEN 'detached-retained' WHEN job.state='pending' THEN 'copy-pending' ELSE 'copied' END);
END $$;
REVOKE ALL ON FUNCTION public.get_occasion_media_job(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_occasion_media_job(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.start_occasion_lifecycle(p_unit bigint,p_organization bigint,p_occasion bigint,p_action text,p_command_id uuid,p_target_unit bigint DEFAULT NULL,p_locale text DEFAULT 'en')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE source_unit bigint; organization_id bigint; target_unit bigint; hash text; job public.occasion_media_jobs; result jsonb; target bigint; manifest jsonb:='[]'; source_url text; field text; target_url text; row_data public.occasions;
BEGIN
 SELECT unit,organization INTO source_unit,organization_id FROM public.occasions WHERE id=p_occasion;
 IF source_unit IS NULL THEN SELECT j.source_unit,j.organization INTO source_unit,organization_id FROM public.occasion_media_jobs j WHERE j.command_id=p_command_id AND j.actor_id=auth.uid(); END IF;
 IF source_unit IS NULL OR (p_unit IS NOT NULL AND p_unit<>source_unit) OR (p_organization IS NOT NULL AND p_organization<>organization_id) THEN RAISE insufficient_privilege USING MESSAGE='occasion scope changed'; END IF;
 target_unit:=coalesce(p_target_unit,source_unit);
 PERFORM public.lock_people_scope_internal_v1(NULL,organization_id,source_unit);
 IF p_action NOT IN ('copy','delete') OR p_action IS NULL OR p_command_id IS NULL OR p_locale NOT IN ('en','cs','sk','de','pl','uk') THEN RAISE invalid_parameter_value USING MESSAGE='invalid lifecycle command'; END IF;
 hash:=encode(extensions.digest(jsonb_build_object('unit',source_unit,'organization',organization_id,'occasion',p_occasion,'action',p_action,'targetUnit',target_unit,'locale',p_locale)::text,'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(p_command_id::text,5319));
 SELECT * INTO job FROM public.occasion_media_jobs WHERE command_id=p_command_id FOR UPDATE;
 IF FOUND THEN
  IF job.request_sha256<>hash OR job.actor_id IS DISTINCT FROM auth.uid() THEN RAISE invalid_parameter_value USING MESSAGE='lifecycle command identity conflict'; END IF;
  PERFORM public.get_occasion_media_job(p_command_id);
  SELECT response INTO result FROM public.client_mutation_receipts WHERE command_id=p_command_id;
  RETURN jsonb_set(result,'{data}',coalesce(result->'data','{}')||jsonb_build_object('mediaJob',public.get_occasion_media_job(p_command_id)));
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=p_occasion AND unit=source_unit AND organization=organization_id) THEN RAISE insufficient_privilege USING MESSAGE='occasion scope changed'; END IF;
 IF p_action='copy' THEN
  IF NOT public.can_copy_occasion_source(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='copy source unavailable'; END IF;
  -- Fence organizer moves through the same stored-scope helper as other tools.
  -- Source forms precede its occasion row, matching the canonical save order.
  PERFORM 1 FROM public.forms WHERE occasion=p_occasion ORDER BY id FOR SHARE;
  PERFORM public.lock_people_scope_internal_v1(p_occasion,organization_id,source_unit);
 END IF;
 IF p_action='delete' THEN
  IF target_unit<>source_unit THEN RAISE invalid_parameter_value USING MESSAGE='delete has no target unit'; END IF;
  result:=public.delete_occasion_client_sync_v1(p_occasion,p_command_id);target:=p_occasion;
  -- The canonical deleter owns its forms/products/occasion lock order. Its
  -- accepted receipt carries the actually locked unit even after row removal.
  -- A move during admission rolls back the entire delete rather than widening consent.
  IF NOT EXISTS(SELECT 1 FROM public.client_mutation_receipts r JOIN public.units u ON u.id=r.unit
    WHERE r.command_id=p_command_id AND r.actor_id=auth.uid() AND r.command_name='occasion.delete'
     AND r.unit=source_unit AND u.organization=organization_id) THEN RAISE insufficient_privilege USING MESSAGE='deleted occasion scope changed'; END IF;
 ELSE
  PERFORM public.lock_people_scope_internal_v1(NULL,organization_id,target_unit);
  result:=public.duplicate_occasion_client_sync_v1(p_occasion,p_command_id,target_unit,p_locale);
  target:=(result#>>'{data,occasionId}')::bigint;
  SELECT * INTO row_data FROM public.occasions WHERE id=target;
  FOREACH field IN ARRAY ARRAY['image','background'] LOOP
   source_url:=CASE WHEN field='image' THEN row_data.data->>'image' ELSE (SELECT f->>'background' FROM jsonb_array_elements(row_data.features) f WHERE f->>'code'='ticket') END;
   IF nullif(source_url,'') IS NULL OR source_url LIKE 'https://img.festapp.net/ticket-presets/v1/%'
    OR EXISTS(SELECT 1 FROM public.images WHERE link=source_url AND occasion=target) THEN CONTINUE; END IF;
   -- Only immutable canonical public objects. Never fetch arbitrary URLs from DB text.
   IF source_url !~ '^https://(a[.])?img[.]festapp[.]net/(images|assets)/[A-Za-z0-9._/-]+$' OR source_url LIKE '%..%' THEN RAISE invalid_parameter_value USING MESSAGE='copy source is not a canonical image'; END IF;
   target_url:='https://img.festapp.net/images/lifecycle/'||p_command_id||'/'||encode(extensions.digest(source_url,'sha256'),'hex');
   manifest:=manifest||jsonb_build_array(jsonb_build_object('field',field,'source',source_url,'target',target_url,'ready',false));
  END LOOP;
 END IF;
 IF result->>'code'<>'200' OR target IS NULL THEN RAISE EXCEPTION 'LIFECYCLE_COMMAND_REJECTED'; END IF;
 INSERT INTO public.occasion_media_jobs(command_id,actor_id,organization,source_unit,target_unit,source_occasion,target_occasion,action,request_sha256,state,media,completed_at)
 VALUES(p_command_id,auth.uid(),organization_id,source_unit,target_unit,p_occasion,target,p_action,hash,CASE WHEN manifest='[]' THEN 'complete' ELSE 'pending' END,manifest,CASE WHEN manifest='[]' THEN now() END);
 RETURN jsonb_set(result,'{data}',coalesce(result->'data','{}')||jsonb_build_object('mediaJob',public.get_occasion_media_job(p_command_id)));
END $$;
REVOKE ALL ON FUNCTION public.start_occasion_lifecycle(bigint,bigint,bigint,text,uuid,bigint,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.start_occasion_lifecycle(bigint,bigint,bigint,text,uuid,bigint,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.record_occasion_media_step(p_command_id uuid,p_index integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE job public.occasion_media_jobs; step jsonb;
BEGIN
 PERFORM public.get_occasion_media_job(p_command_id);
 SELECT * INTO job FROM public.occasion_media_jobs WHERE command_id=p_command_id FOR UPDATE;
 IF p_index IS NULL OR p_index<0 OR p_index>=jsonb_array_length(job.media) THEN RAISE invalid_parameter_value USING MESSAGE='invalid media step'; END IF;
 step:=job.media->p_index;
 IF step->>'ready'='true' THEN RETURN public.get_occasion_media_job(p_command_id); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.images WHERE link=step->>'target' AND occasion=job.target_occasion) THEN
  PERFORM public.add_image_record(step->>'target',job.target_occasion,NULL);
 END IF;
 UPDATE public.occasion_media_jobs SET media=jsonb_set(media,ARRAY[p_index::text,'ready'],'true') WHERE command_id=p_command_id;
 RETURN public.get_occasion_media_job(p_command_id);
END $$;
REVOKE ALL ON FUNCTION public.record_occasion_media_step(uuid,integer) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.record_occasion_media_step(uuid,integer) TO authenticated;

CREATE OR REPLACE FUNCTION public.finish_occasion_media_job(p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE job public.occasion_media_jobs; occasion_row public.occasions; features jsonb; settings jsonb:='{}'; step jsonb; config jsonb; ver bigint; result jsonb;
BEGIN
 PERFORM public.get_occasion_media_job(p_command_id);
 SELECT * INTO job FROM public.occasion_media_jobs WHERE command_id=p_command_id FOR UPDATE;
 IF job.state='complete' THEN RETURN public.get_occasion_media_job(p_command_id); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(job.media) x WHERE x->>'ready'<>'true') THEN RAISE object_not_in_prerequisite_state USING MESSAGE='media is pending'; END IF;
 -- Same forms -> occasion order as the canonical save owner.
 PERFORM 1 FROM public.forms WHERE occasion=job.target_occasion ORDER BY id FOR UPDATE;
 SELECT * INTO occasion_row FROM public.occasions WHERE id=job.target_occasion AND unit=job.target_unit AND organization=job.organization FOR UPDATE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='copy target unavailable'; END IF;
 features:=occasion_row.features;
 FOR step IN SELECT * FROM jsonb_array_elements(job.media) LOOP
  IF step->>'field'='image' AND occasion_row.data->>'image'=step->>'source' THEN settings:=settings||jsonb_build_object('image',step->'target');
  ELSIF step->>'field'='background' THEN
   SELECT coalesce(jsonb_agg(CASE WHEN f->>'code'='ticket' AND f->>'background'=step->>'source' THEN f||jsonb_build_object('background',step->'target') ELSE f END),'[]') INTO features FROM jsonb_array_elements(features) f;
  END IF;
 END LOOP;
 -- Preserve any newer user-selected image and every unrelated setting/feature.
 SELECT coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='occasion' AND scope_type='occasion' AND scope_id=job.target_occasion AND aggregate_id=job.target_occasion::text),0) INTO ver;
 config:=jsonb_build_object('id',job.target_occasion,'settings',settings,'features',features);
 result:=public.save_occasion_client_sync_v1(job.target_occasion,job.apply_command,ver,config);
 IF result->>'code'<>'200' THEN RAISE serialization_failure USING MESSAGE='copy media apply must retry same job'; END IF;
 UPDATE public.occasion_media_jobs SET state='complete',completed_at=now() WHERE command_id=p_command_id;
 RETURN public.get_occasion_media_job(p_command_id);
END $$;
REVOKE ALL ON FUNCTION public.finish_occasion_media_job(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.finish_occasion_media_job(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_pending_occasion_media_jobs(p_unit bigint,p_organization bigint,p_limit integer DEFAULT 50)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,p_organization,p_unit);
 IF NOT public.can_copy_occasion_target(p_unit) OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE insufficient_privilege USING MESSAGE='organizer manager required'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page."createdAt",page."commandId"),'[]') INTO result FROM (
  SELECT command_id AS "commandId",target_occasion AS "occasionId",target_unit AS "targetUnitId",source_unit AS "unitId",state,created_at AS "createdAt"
  FROM public.occasion_media_jobs WHERE actor_id=auth.uid() AND organization=p_organization AND (source_unit=p_unit OR target_unit=p_unit) AND state='pending' ORDER BY created_at,command_id LIMIT p_limit) page;
 RETURN jsonb_build_object('items',result);
END $$;
REVOKE ALL ON FUNCTION public.get_pending_occasion_media_jobs(bigint,bigint,integer) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_pending_occasion_media_jobs(bigint,bigint,integer) TO authenticated;

CREATE OR REPLACE FUNCTION public.manage_occasion_setup_authoring(p_unit bigint,p_organization bigint,p_draft uuid,p_expected_revision bigint DEFAULT NULL,p_command_id uuid DEFAULT NULL,p_source_scopes jsonb DEFAULT '[]')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE draft public.occasion_setup_drafts; source bigint; binding jsonb; source_ids bigint[];
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,p_organization,p_unit);
 IF NOT public.can_create_occasion(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='setup author required'; END IF;
 SELECT * INTO draft FROM public.occasion_setup_drafts WHERE id=p_draft AND unit=p_unit AND organization=p_organization FOR UPDATE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='setup draft unavailable'; END IF;
 IF p_command_id IS NULL THEN RETURN public.get_occasion_setup_draft(p_draft); END IF;
 IF draft.data ? 'finalizeResponse' THEN RETURN public.finalize_occasion_setup_draft(p_draft,p_expected_revision,p_command_id); END IF;
 IF draft.revision<>p_expected_revision AND NOT EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=auth.uid() AND unit=p_unit AND command_name='occasion.setup.finalize') THEN RAISE serialization_failure USING MESSAGE='setup draft changed'; END IF;
 source_ids:=ARRAY(SELECT DISTINCT x::bigint FROM unnest(ARRAY[draft.data->>'sourceId',draft.data->>'formSourceOccasionId',draft.data->>'blueprintSourceOccasionId']) x WHERE nullif(x,'') IS NOT NULL);
 IF jsonb_typeof(p_source_scopes) IS DISTINCT FROM 'array' OR jsonb_array_length(p_source_scopes)<>cardinality(source_ids) THEN RAISE insufficient_privilege USING MESSAGE='source consent required'; END IF;
 FOREACH source IN ARRAY source_ids LOOP
  SELECT x INTO binding FROM jsonb_array_elements(p_source_scopes) x WHERE (x->>'occasionId')::bigint=source;
  IF binding IS NULL THEN RAISE insufficient_privilege USING MESSAGE='source consent required'; END IF;
  PERFORM public.lock_people_scope_internal_v1(source,p_organization,(binding->>'unitId')::bigint);
  IF NOT public.can_copy_occasion_source(source) THEN RAISE insufficient_privilege USING MESSAGE='source read denied'; END IF;
 END LOOP;
 RETURN public.finalize_occasion_setup_draft(p_draft,p_expected_revision,p_command_id);
END $$;
REVOKE ALL ON FUNCTION public.manage_occasion_setup_authoring(bigint,bigint,uuid,bigint,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.manage_occasion_setup_authoring(bigint,bigint,uuid,bigint,uuid,jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.check_lifecycle_source_scope(p_occasion bigint,p_organization bigint,p_unit bigint)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF NOT public.can_copy_occasion_source(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='source unavailable'; END IF;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.check_lifecycle_source_scope(bigint,bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.check_lifecycle_source_scope(bigint,bigint,bigint) TO authenticated;


-- Source: database/functions/authoring/order_deletion.sql
-- The ordinary deletion context/SQL receipt and Fakturoid gateway remain the
-- effect owners. Scope and inspected revision fence their delegated transport.
CREATE OR REPLACE FUNCTION public.check_delegated_order_deletion_scope_internal_v1(p_occasion bigint,p_organization bigint,p_unit bigint,p_order bigint,p_command_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_delete_orders(p_occasion) OR NOT EXISTS(
  SELECT 1 FROM public.occasions o JOIN public.user_info viewer ON viewer.id=auth.uid() AND viewer.organization=o.organization
  WHERE o.id=p_occasion AND o.organization=p_organization AND (p_unit IS NULL OR o.unit=p_unit)) OR NOT (
  EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_order AND occasion=p_occasion)
  OR EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id AND occasion=p_occasion AND actor_id=auth.uid() AND command_name='inventory.order.delete'
   AND request_sha256=encode(extensions.digest(convert_to(jsonb_build_object('order',p_order)::text,'UTF8'),'sha256'),'hex'))) THEN RAISE insufficient_privilege USING MESSAGE='order deletion unavailable'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.check_delegated_order_deletion_scope_internal_v1(bigint,bigint,bigint,bigint,uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.get_delegated_order_deletion_context(p_occasion bigint,p_organization bigint,p_unit bigint,p_order bigint,p_command_id uuid DEFAULT NULL,p_expected_revision text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 -- Deny unauthorized targets before acquiring a global send fence or foreign locks.
 PERFORM public.check_delegated_order_deletion_scope_internal_v1(p_occasion,p_organization,p_unit,p_order,p_command_id);
 -- Preserve the canonical email -> form -> order/capacity -> occasion order.
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 PERFORM 1 FROM public.forms WHERE id=(SELECT form FROM eshop.orders WHERE id=p_order) FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_order) THEN PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]); END IF;
 PERFORM public.check_operator_order_scope_internal_v1(p_occasion,p_organization,p_unit,false);
 PERFORM public.check_delegated_order_deletion_scope_internal_v1(p_occasion,p_organization,p_unit,p_order,p_command_id);
 result:=public.get_order_deletion_context_v1(p_order,p_command_id);
 IF result ? 'response' THEN RETURN result; END IF;
 IF p_expected_revision IS NOT NULL AND p_expected_revision IS DISTINCT FROM public.operator_order_revision_internal_v1(p_order) THEN RAISE serialization_failure USING MESSAGE='order changed before deletion'; END IF;
 RETURN result||jsonb_build_object('revision',public.operator_order_revision_internal_v1(p_order));
END $$;
REVOKE ALL ON FUNCTION public.get_delegated_order_deletion_context(bigint,bigint,bigint,bigint,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_delegated_order_deletion_context(bigint,bigint,bigint,bigint,uuid,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.delete_delegated_order_client_sync_v1(p_occasion bigint,p_organization bigint,p_unit bigint,p_order bigint,p_command_id uuid,p_expected_revision text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 IF p_expected_revision IS NULL OR p_expected_revision !~ '^[a-f0-9]{64}$' THEN RAISE invalid_parameter_value USING MESSAGE='original deletion revision required'; END IF;
 result:=public.get_delegated_order_deletion_context(p_occasion,p_organization,p_unit,p_order,p_command_id,p_expected_revision);
 IF result ? 'response' THEN RETURN result->'response'; END IF;
 RETURN public.delete_order_client_sync_v1(p_order,p_command_id);
END $$;
REVOKE ALL ON FUNCTION public.delete_delegated_order_client_sync_v1(bigint,bigint,bigint,bigint,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.delete_delegated_order_client_sync_v1(bigint,bigint,bigint,bigint,uuid,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.delete_order_history_client_sync_v1(p_history_id bigint,p_command_id uuid,p_occasion bigint DEFAULT NULL,p_organization bigint DEFAULT NULL,p_unit bigint DEFAULT NULL,p_order bigint DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE order_id bigint; occasion_id bigint; unit_id bigint; hash text; receipt public.client_mutation_receipts; begun jsonb;
BEGIN
 IF auth.uid() IS NULL OR p_command_id IS NULL THEN RAISE insufficient_privilege USING MESSAGE='authenticated history command required'; END IF;
 hash:=encode(extensions.digest(jsonb_build_object('history',p_history_id)::text,'sha256'),'hex');
 SELECT h."order",o.occasion,oc.unit INTO order_id,occasion_id,unit_id FROM eshop.orders_history h JOIN eshop.orders o ON o.id=h."order" JOIN public.occasions oc ON oc.id=o.occasion WHERE h.id=p_history_id;
 SELECT * INTO receipt FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=auth.uid() AND command_name='unit.order_history.delete' AND request_sha256=hash;
 IF occasion_id IS NULL AND receipt.status IN ('completed','expired') THEN
  order_id:=(receipt.response#>>'{data,orderId}')::bigint;occasion_id:=(receipt.response#>>'{data,occasionId}')::bigint;
  SELECT unit INTO unit_id FROM public.occasions WHERE id=occasion_id;
 END IF;
 IF occasion_id IS NULL OR (p_order IS NOT NULL AND p_order<>order_id) OR (p_occasion IS NOT NULL AND p_occasion<>occasion_id) THEN RAISE insufficient_privilege USING MESSAGE='history entry unavailable'; END IF;
 PERFORM public.lock_people_scope_internal_v1(occasion_id,p_organization,p_unit);
 IF NOT public.can_manage_unit_configuration(unit_id) OR public.is_demo_unit(unit_id) THEN RAISE insufficient_privilege USING MESSAGE='organizer manager required'; END IF;
 IF receipt.status='completed' THEN RETURN receipt.response; ELSIF receipt.status='expired' THEN RETURN public.expired_client_mutation_response_v1(receipt); END IF;
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.order_history.delete',unit_id,auth.uid(),hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 PERFORM public.delete_order_history(p_history_id);
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,unit_id,'unit.order_history.delete','order_history',p_history_id,'delete',jsonb_build_object('historyId',p_history_id,'orderId',order_id,'occasionId',occasion_id));
END $$;
REVOKE ALL ON FUNCTION public.delete_order_history_client_sync_v1(bigint,uuid,bigint,bigint,bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.delete_order_history_client_sync_v1(bigint,uuid,bigint,bigint,bigint,bigint) TO authenticated;
